<script setup lang="ts">
import{ref,computed}from'vue';import{useRouter}from'vue-router';import{MapPin,ChevronDown,X,Search}from'lucide-vue-next';import{states,cities}from'../../composables/useLocations';import{normalize}from'../../utils/format';
const props=defineProps<{uf:string;city:string|null}>();const router=useRouter();const expanded=ref(false),search=ref('');const state=computed(()=>states.value.find(s=>s.uf===props.uf));const currentCity=computed(()=>cities.value.find(c=>c.uf===props.uf&&c.slug===props.city));const items=computed(()=>search.value.trim()?[...states.value.filter(s=>normalize(s.name).includes(normalize(search.value))).map(s=>({name:s.name,path:`/estado/${s.uf}`})),...cities.value.filter(c=>(props.uf==='br'||c.uf===props.uf)&&normalize(c.name).includes(normalize(search.value))).slice(0,30).map(c=>({name:c.name+' — '+c.uf.toUpperCase(),path:`/estado/${c.uf}/${c.slug}`}))]:states.value.map(s=>({name:s.name,path:`/estado/${s.uf}`})));function select(path:string){expanded.value=false;search.value='';router.push(path)}
</script>
<template><div class="location-picker"><button class="location-trigger" :aria-expanded="expanded" @click="expanded=!expanded"><MapPin :size="19"/><span><small>Localização</small><strong>{{state?.name||'Brasil'}}<template v-if="currentCity"> / {{currentCity.name}}</template></strong></span><ChevronDown :size="17"/></button><div v-if="expanded" class="location-popover" @keydown.esc="expanded=false"><div class="flex items-center justify-between"><strong>Escolha uma localização</strong><button class="icon-button" aria-label="Fechar localidades" @click="expanded=false"><X :size="17"/></button></div><label class="input-search"><Search :size="17"/><input v-model="search" aria-label="Buscar localização" placeholder="Estado ou município"></label><button class="location-option" @click="select('/brasil')">Brasil <span>Resultado nacional</span></button><div class="location-options"><button v-for="item in items" :key="item.path" class="location-option" @click="select(item.path)">{{item.name}}</button><p v-if="!items.length">Nenhuma localização encontrada.</p></div></div></div></template>
